const deliveryForm=document.querySelector('#delivery-form');
if(deliveryForm)deliveryForm.addEventListener('submit',event=>{event.preventDefault();if(!deliveryForm.reportValidity())return;const data=new FormData(deliveryForm);const lines=['LumiBrain™ delivery request — payment requires merchant verification',''];for(const [key,value] of data)lines.push(key+': '+String(value).replace(/[\r\n]/g,' '));window.location.href='mailto:yiweiinc99@gmail.com?subject='+encodeURIComponent('LumiBrain delivery details / '+data.get('transaction'))+'&body='+encodeURIComponent(lines.join('\n'));});
